INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(52645235, 'Epurrely Happiness', '爱皮尔莉・幸福', 'エピュアリィ・ハピネス', 'XYZ Monster', 'Fairy', 'LIGHT', 2, 2000, 100, '2星怪兽×2 ①：这张卡进行战斗的伤害步骤结束时才能发动。从卡组把1张「纯爱妖精」卡加入手卡。这张卡有「纯爱妖精快乐回忆」在作为超量素材的场合，可以选场上1只表侧表示怪兽把攻击力变成一半。 ②：自己把「纯爱妖精」速攻魔法卡发动时才能发动。场上的那张卡在下面重叠作为超量素材。那之后，可以选对方场上1张魔法·陷阱卡回到持有者手卡。这个效果1回合可以使用最多3次。'),
(62592805, 'Epurrely Noir', '爱皮尔莉・黑夜', 'エピュアリィ・ノアール', 'XYZ Monster', 'Fairy', 'DARK', 2, 1000, 2000, '2星怪兽×2 ①：1回合1次，丢弃1张手卡，以对方场上1张卡为对象才能发动（这张卡有「纯爱妖精瞌睡回忆」在作为超量素材的场合，对象可以变成2张）。那张卡回到手卡。 ②：1回合最多3次，自己把「纯爱妖精」速攻魔法卡发动时才能发动。场上的那张卡作为这张卡的超量素材。那之后，可以从卡组把1张「纯爱妖精」陷阱卡在自己场上盖放。'),
(24434049, 'Epurrely Plump', '爱皮尔莉・圆满', 'エピュアリィ・プランプ', 'XYZ Monster', 'Fairy', 'EARTH', 2, 200, 2100, '2星怪兽×2 ①：1回合1次，以自己或者对方的墓地的魔法·陷阱卡合计最多2张为对象才能发动。那些卡在这张卡下面重叠作为超量素材。这张卡有「纯爱妖精美味回忆」在作为超量素材的场合，这个效果在对方回合也能发动。 ②：自己把「纯爱妖精」速攻魔法卡发动时才能发动。场上的那张卡在这张卡下面重叠作为超量素材。那之后，可以选场上1只怪兽直到结束阶段除外。这个效果1回合可以使用最多3次。'),
(62878208, 'Equip Shot', '装备喷射球', 'イクイップ・シュート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '战斗阶段中才能发动。选择自己场上表侧攻击表示存在的怪兽装备的1张装备卡和对方场上存在的1只表侧攻击表示的怪兽，把选择的装备卡给选择的对方怪兽装备。那之后，选择的装备卡装备过的自己怪兽和选择的对方怪兽进行战斗进行伤害计算。'),
(94716515, 'Eradicating Aerosol', '尖刺神的杀虫剂', 'トゲトゲ神の殺虫剤', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的昆虫族怪兽全部破坏。'),
(54974237, 'Eradicator Epidemic Virus', '暗之牌组破坏病毒', '闇のデッキ破壊ウイルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只攻击力2500以上的暗属性怪兽解放，宣言卡的种类（魔法·陷阱）才能发动。对方场上的魔法·陷阱卡，对方手卡，用对方回合计算的3回合内对方抽到的卡全部确认，那之内的宣言种类的卡全部破坏。'),
(23064604, 'Erebus the Underworld Monarch', '冥帝厄瑞玻斯', '冥帝エレボス', 'Effect Monster', 'Zombie', 'DARK', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。 ①：这张卡上级召唤的场合才能发动。从手卡·卡组把「帝王」魔法·陷阱卡2种类各1张送去墓地，从对方的手卡·场上·墓地让1张卡回到卡组（从手卡是随机选）。 ②：这张卡在墓地存在的场合，1回合1次，自己·对方的主要阶段，从手卡丢弃1张「帝王」魔法·陷阱卡，以自己墓地1只攻击力2400以上而守备力1000的怪兽为对象才能发动。那只怪兽加入手卡。'),
(15746348, 'Eria the Water Channeler', '水灵媒师 艾里雅', '水霊媒師エリア', 'Effect Monster', 'Spellcaster', 'WATER', 5, 1850, 1500, '这个卡名在规则上也当作「灵使」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只水属性怪兽丢弃才能发动。把持有这张卡以外的丢弃的怪兽的等级以上的等级的1只水属性怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不能把水属性以外的怪兽的效果发动。 ②：自己的水属性怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。'),
(74364659, 'Eria the Water Charmer', '水灵使 艾里雅', '水霊使いエリア', 'Flip Effect Monster', 'Spellcaster', 'WATER', 3, 500, 1500, '①：这张卡反转的场合，以对方场上1只水属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到作为对象的怪兽的控制权。'),
(73309655, 'Eria the Water Charmer, Gentle', '清冽之水灵使 艾里雅', '清冽の水霊使いエリア', 'Link Monster', 'Spellcaster', 'WATER', NULL, 1850, NULL, '包含水属性怪兽的怪兽2只 这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以对方墓地1只水属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的水属性怪兽加入手卡。'),
(7407724, 'Erica the Rikka Fairy', '六花精欧石楠', '六花精エリカ', 'Effect Monster', 'Plant', 'WATER', 6, 2400, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡以外的自己的植物族怪兽进行战斗的攻击宣言时，把手卡·场上的这张卡解放才能发动。那只自己怪兽的攻击力·守备力直到回合结束时上升1000。 ②：这张卡在墓地存在的状态，自己场上的植物族怪兽被解放的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(18235309, 'Escalation of the Monarchs', '连击的帝王', '連撃の帝王', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，对方的主要阶段以及战斗阶段才能把这个效果发动。把1只怪兽上级召唤。'),
(31550470, 'Escape from the Dark Dimension', '暗次元的解放', '闇次元の解放', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以除外的1只自己的暗属性怪兽为对象才能把这张卡发动。那只怪兽特殊召唤。这张卡从场上离开时那只怪兽破坏并除外。那只怪兽破坏时这张卡破坏。'),
(53417695, 'Escape of the Unchained', '破械唱导', '破械唱導', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「破械」怪兽和场上1张卡为对象才能发动。那2张卡破坏。 ②：盖放的这张卡被效果破坏的场合才能发动。从卡组把1只「破械」怪兽特殊召唤。'),
(33676146, 'Escapegoat', '逃脱替罪山羊', 'エスケープ・ゴート', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：衍生物以外的自己场上的怪兽为对象的效果由对方发动时，把自己场上1只怪兽解放才能发动。在自己场上把1只「逃羊衍生物」（兽族·地·1星·攻/守0）守备表示特殊召唤。 ②：衍生物以外的自己场上的怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1只衍生物破坏。'),
(24326617, 'Escher the Frost Vassal', '冰帝家臣埃舍尔', '氷帝家臣エッシャー', 'Effect Monster', 'Aqua', 'WATER', 4, 800, 1000, '①：对方的魔法与陷阱区域有卡2张以上存在的场合，这张卡可以从手卡特殊召唤。'),
(84653834, 'ESP Amplifier', '超能力增幅器', '超能力増幅器', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡的发动时，自己场上表侧表示存在的全部念动力族怪兽的攻击力上升从游戏中除外的自己的念动力族怪兽数量×300的数值。受到这个效果影响的怪兽在结束阶段时从游戏中除外。'),
(99070951, 'Esper Girl', '超能力女孩', 'サイ・ガール', 'Tuner Monster', 'Psychic', 'EARTH', 2, 500, 300, '从游戏中除外的这张卡特殊召唤成功时，把自己卡组最上面的卡里侧表示从游戏中除外。这张卡从场上送去墓地时，这张卡的效果除外的自己的卡加入手卡。'),
(45283341, 'Eternal Bond', '永恒之绊', 'エターナル・ボンド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地的「光子」怪兽任意数量为对象才能发动。那些怪兽效果无效特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以对方场上1只「光子」怪兽为对象才能发动。得到那只怪兽的控制权。这个回合，自己不用那只怪兽不能攻击宣言，那只怪兽的攻击力变成自己场上的「光子」怪兽的原本攻击力合计数值。'),
(25750986, 'Eternal Chaos', '永恒混沌', 'エターナル・カオス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只表侧表示怪兽为对象才能发动。攻击力合计最多到那只怪兽的攻击力以下为止，从卡组把光属性和暗属性的怪兽各1只送去墓地。这张卡的发动后，直到回合结束时自己只能有1次把墓地的怪兽的效果发动。'),
(35787450, 'Eternal Dread', '无尽的恐惧', 'エターナル・ドレッド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「幽狱之时计塔」放置2个时计指示物。'),
(56606928, 'Eternal Drought', '永远的渴水', '永遠の渇水', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的鱼族怪兽全部破坏。'),
(87532344, 'Eternal Favorite', '永恒至爱', 'エターナル・フェイバリット', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己的墓地·除外状态的1只「于贝尔」怪兽特殊召唤。在那次特殊召唤成功时双方不能把魔法·陷阱·怪兽的效果发动。 ●自己场上有「于贝尔」存在的场合，丢弃1张手卡，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。包含「于贝尔」怪兽的自己·对方场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(82162616, 'Eternal Galaxy', '永远之银河', '永遠なる銀河', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「光子」怪兽或「银河」怪兽存在的场合，以自己场上1只超量怪兽为对象才能发动。比那只自己怪兽阶级高4阶的1只「光子」超量怪兽或「银河」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(95051344, 'Eternal Rest', '成佛', '成仏', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '有装备卡装备的怪兽全部破坏。'),
(48680970, 'Eternal Soul', '永远之魂', '永遠の魂', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●从自己的手卡·墓地把1只「黑魔术师」特殊召唤。 ●从卡组把1张「黑·魔·导」或「千把刀」加入手卡。 ②：只要这张卡在魔法与陷阱区域存在，自己的怪兽区域的「黑魔术师」不受对方的效果影响。 ③：表侧表示的这张卡从场上离开的场合发动。自己场上的怪兽全部破坏。'),
(28903523, 'Eternal Sunshine', '永恒阳光', 'エターナル・サンシャイン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果在1回合中可以使用最多有自己场上的「古代妖精龙」以及有那个卡名记述的怪兽数量的次数。 ①：自己场上的怪兽的守备力上升自己场上的「古代妖精龙」以及有那个卡名记述的怪兽数量×500。 ②：以对方场上1只表侧表示怪兽为对象才能发动（同一连锁上最多1次）。那只怪兽直到回合结束时攻击力·守备力变成一半，效果无效化。'),
(11460577, 'Etoile Cyber', '电子化明星', 'エトワール・サイバー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 1600, '①：这张卡直接攻击的伤害步骤内，攻击力上升500。'),
(45675980, 'Etude of the Branded', '烙印的即凶剧', '烙印の即凶劇', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方回合可以发动。用包含龙族怪兽的自己场上的怪兽为素材进行同调召唤。 ②：只要自己场上有「深渊之兽」怪兽存在，为对方的仪式召唤而被解放送去对方墓地的怪兽以及成为对方的融合·同调·连接召唤的素材送去对方墓地的怪兽不去墓地而除外。'),
(71228611, 'Eucalyptus Mole', '桉树鼹鼠', 'ユーカリ・モール', 'Effect Monster', 'Plant', 'EARTH', 3, 300, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只4星以下的兽族怪兽里侧守备表示特殊召唤。这张卡是攻击表示的场合，再让这张卡变成守备表示。 ②：这张卡被破坏的场合才能发动。从卡组把1只「树熊」怪兽特殊召唤，直到下个回合的结束时以下效果适用。 ●效果怪兽以外的自己场上的兽族怪兽的攻击力上升自身的原本守备力数值。'),
(9547962, 'Euler''s Circuit', '欧拉回路', 'オイラーサーキット', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上有「廷达魔三角」怪兽3只以上存在的场合，对方怪兽不能攻击。 ②：自己准备阶段，以自己场上1只「廷达魔三角」怪兽为对象才能发动。那只怪兽的控制权移给对方。 ③：把墓地的这张卡除外，从手卡丢弃1张「廷达魔三角」卡才能发动。从卡组把1张「欧拉回路」加入手卡。'),
(40177746, 'Eva', '异娃', 'イーバ', 'Effect Monster', 'Fairy', 'LIGHT', 1, 500, 200, '这个卡名的效果1回合只能使用1次。 ①：这张卡被送去墓地的场合，把这张卡以外的自己的场上·墓地最多2只天使族·光属性怪兽除外才能发动。把除外数量的「地外生命」以外的2星以下的天使族·光属性怪兽从卡组加入手卡（同名卡最多1张）。'),
(64382840, 'Eva Token', '网罟座泽塔星人', 'ゼータ・レティキュラント', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(32013448, 'Evening Twilight Knight', '宵暗之骑士', '宵闇の騎士', 'Effect Monster', 'Warrior', 'DARK', 4, 500, 2000, '「宵暗之骑士」的①②的效果1回合各能使用1次。 ①：使用这张卡仪式召唤的「混沌战士」怪兽得到以下效果。 ●1回合1次，以对方场上1只怪兽为对象才能发动。那只怪兽除外。 ●1回合1次，自己主要阶段才能发动。对方手卡随机选1张直到下次的对方结束阶段里侧表示除外。 ②：墓地的这张卡被除外的场合才能发动。从卡组把1只仪式怪兽加入手卡。'),
(15693423, 'Evenly Matched', '颉颃胜负', '拮抗勝負', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上没有卡存在的场合，这张卡的发动从手卡也能用。 ①：对方场上的卡数量比自己场上的卡多的场合，自己·对方的战斗阶段结束时才能发动。直到变成和自己场上的卡数量相同为止，对方必须选自身场上的卡里侧表示除外。'),
(37042505, 'Everlasting Alloy', '不朽的特殊合金', '不朽の特殊合金', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有「人造人-念力震慑者」存在的场合，可以从以下效果选择1个发动。 ●自己场上的全部机械族怪兽直到回合结束时不会被对方的效果破坏。 ●自己场上的机械族怪兽为对象的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。'),
(31467372, 'Everliving Underworld Cannon', '不死式冥界炮', '不死式冥界砲', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有不死族怪兽特殊召唤时，给与对方基本分800分伤害。这个效果1回合只能使用1次。'),
(45222299, 'Evigishki Gustkraken', '禁咒仪・幽灵克拉肯', 'イビリチュア・ガストクラーケ', 'Ritual Effect Monster', 'Aqua', 'WATER', 6, 2400, 1000, '「遗式」仪式魔法卡降临。 ①：这张卡仪式召唤成功的场合发动。对方手卡随机选最多2张确认，选那之内的1张回到卡组。'),
(71203602, 'Evigishki Levianima', '禁咒仪・女相利维亚', 'イビリチュア・リヴァイアニマ', 'Ritual Effect Monster', 'Aqua', 'WATER', 8, 2700, 1500, '名字带有「遗式」的仪式魔法卡降临。这张卡的攻击宣言时，从自己卡组抽1张卡，给双方确认。确认的卡是名字带有「遗式」的怪兽的场合，把对方手卡随机1张确认。'),
(76372778, 'Evigishki Merrowgeist', '禁咒仪・幽魂梅洛欧', 'イビリチュア・メロウガイスト', 'XYZ Monster', 'Aqua', 'WATER', 4, 2100, 1600, '4星怪兽×2 这张卡战斗破坏对方怪兽的场合，那次伤害计算后可以把这张卡1个超量素材取除，破坏的那只怪兽不送去墓地回到持有者卡组。'),
(11877465, 'Evigishki Mind Augus', '禁咒仪・心灵女食人魔', 'イビリチュア・マインドオーガス', 'Ritual Effect Monster', 'Aqua', 'WATER', 6, 2500, 2000, '名字带有「遗式」的仪式魔法卡降临。这张卡仪式召唤成功时，选择双方墓地存在的卡合计最多5张，回到持有者卡组。'),
(88926295, 'Evigishki Neremanas', '禁咒仪・灵智涅瑞伊斯', 'イビリチュア・ネーレイマナス', 'Ritual Effect Monster', 'Spellcaster', 'WATER', 10, 3000, 1800, '「遗式」仪式魔法卡降临。 ①：这张卡仪式召唤成功的场合，以自己墓地1只水属性怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡不会被和从额外卡组特殊召唤的怪兽的战斗破坏。 ③：1回合1次，对方把怪兽的效果发动时才能发动。选自己场上1只「遗式」仪式怪兽回到持有者手卡，那个发动无效并回到持有者卡组。'),
(57272170, 'Evigishki Soul Ogre', '禁咒仪・灵魂食人魔', 'イビリチュア・ソウルオーガ', 'Ritual Effect Monster', 'Aqua', 'WATER', 8, 2800, 2800, '名字带有「遗式」的仪式魔法卡降临。1回合1次，可以从手卡把1只名字带有「遗式」的怪兽丢弃，选择对方场上表侧表示存在的1张卡回到持有者卡组。'),
(21496848, 'Evigishki Tetrogre', '禁咒仪・四面体巨魔', 'イビリチュア・テトラオーグル', 'Ritual Effect Monster', 'Aqua', 'WATER', 6, 2600, 2100, '名字带有「遗式」的仪式魔法卡降临。1回合1次，宣言卡的种类（怪兽·魔法·陷阱）才能发动。对方可以丢弃1张手卡让这个效果无效。没丢弃的场合，双方玩家把宣言的种类的1张卡从卡组送去墓地。'),
(3519195, 'Evil Assault', '邪恶强袭', 'イービル・アサルト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。从卡组选1只4星以下的「邪心英雄」怪兽加入手卡或特殊召唤。这张卡的发动后，直到回合结束时自己不是「英雄」怪兽不能从额外卡组特殊召唤。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。从自己墓地把1张「暗黑融合」加入手卡。'),
(15684835, 'Evil Blast', '邪心爆破', 'イービル・ブラスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上有怪兽特殊召唤时才能发动。发动后，变成攻击力上升500的装备卡，给那只怪兽装备。每次对方回合的准备阶段给与对方基本分500分伤害。'),
(8400623, 'Evil Dragon Ananta', '邪龙 阿难陀', '邪龍アナンタ', 'Effect Monster', 'Reptile', 'DARK', 8, -1, -1, '这张卡不能通常召唤。从自己墓地以及自己场上的表侧表示怪兽之中把爬虫类族怪兽全部除外的场合才能特殊召唤。 ①：这张卡的攻击力·守备力变成因为这张卡特殊召唤而除外的怪兽数量×600。 ②：自己结束阶段，以场上1张卡为对象发动。这张卡在自己场上表侧表示存在的场合，作为对象的卡破坏。'),
(17616743, 'Evil Eye Awakening', '唤忌之咒眼', '喚忌の呪眼', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地选1只「咒眼」怪兽特殊召唤。自己的魔法与陷阱区域有「太阴之咒眼」存在的场合，也能作为代替从卡组把1只「咒眼」怪兽特殊召唤。'),
(43011492, 'Evil Eye Confrontation', '惨祸之咒眼', '惨禍の呪眼', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「咒眼」怪兽存在的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。自己的魔法与陷阱区域有「太阴之咒眼」存在的场合，这个效果破坏的卡不去墓地而除外。'),
(6494106, 'Evil Eye Defeat', '妒绝之咒眼', '妬絶の呪眼', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「咒眼」怪兽存在的场合，以场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。自己的魔法与陷阱区域有「太阴之咒眼」存在的场合，这个效果的对象可以变成2只。'),
(70122149, 'Evil Eye Domain - Pareidolia', '咒眼领阈-错视之城-', '呪眼領閾－パレイドリア－', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「咒眼」怪兽加入手卡。 ②：1回合1次，自己的魔法与陷阱区域有「太阴之咒眼」存在，自己的「咒眼」怪兽被攻击的伤害计算时才能发动。那次战斗发生的对自己的战斗伤害让对方也承受。 ③：场地区域的这张卡被效果破坏的场合，以自己墓地1只「咒眼」怪兽为对象才能发动。那只怪兽加入手卡。'),
(42899204, 'Evil Eye Mesmerism', '死配之咒眼', '死配の呪眼', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方把怪兽攻击表示特殊召唤时，持有比那只怪兽高的攻击力的「咒眼」怪兽在自己场上存在的场合以那1只对方怪兽为对象才能把这张卡发动。得到那只怪兽的控制权。那只怪兽只要自己的魔法与陷阱区域有「太阴之咒眼」存在，也当作「咒眼」怪兽使用。那只怪兽从场上离开时这张卡破坏。'),
(28957126, 'Evil Eye of Gorgoneio', '蛇发之咒眼', 'ゴルゴネイオの呪眼', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「咒眼」怪兽才能装备。这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：这张卡只要在魔法与陷阱区域存在，卡名当作「太阴之咒眼」使用。 ②：自己基本分比对方少的场合，装备怪兽的攻击力上升基本分差的数值。 ③：把墓地的这张卡除外，从手卡丢弃1张「咒眼」卡才能发动。从卡组把「蛇发之咒眼」以外的1张「咒眼」魔法·陷阱卡加入手卡。'),
(44133040, 'Evil Eye of Selene', '太阴之咒眼', 'セレンの呪眼', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「咒眼」怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：装备怪兽不会被战斗以及对方的效果破坏，不会成为对方的效果的对象。 ②：每次自己把装备怪兽的效果或者这张卡以外的「咒眼」魔法·陷阱卡发动才发动。装备怪兽的攻击力上升500，自己失去500基本分。 ③：支付1000基本分，从自己墓地把「太阴之咒眼」以外的1张「咒眼」魔法·陷阱卡除外才能发动。墓地的这张卡在自己场上盖放。'),
(7610394, 'Evil Eye Reemergence', '眷现之咒眼', '眷現の呪眼', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：在自己场上把1只「咒眼之眷属衍生物」（恶魔族·暗·1星·攻/守400）特殊召唤。自己的魔法与陷阱区域有「太阴之咒眼」存在的场合，这个效果特殊召唤的数量可以变成2只。这张卡的发动后，直到回合结束时自己不是恶魔族怪兽不能特殊召唤。 ②：把墓地的这张卡除外才能发动。这个回合，自己场上的「咒眼」魔法·陷阱卡不会成为对方的效果的对象。'),
(79400597, 'Evil Eye Repose', '静冠之咒眼', '静冠の呪眼', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡也能从自己墓地把1张「咒眼」卡除外来发动。那个场合，自己从卡组抽1张。 ②：1回合1次，有「太阴之咒眼」装备的自己的「咒眼」怪兽向对方怪兽攻击的伤害计算后才能发动。那只对方怪兽除外。 ③：魔法与陷阱区域的这张卡被效果破坏的场合，以除外的最多3张自己的「咒眼」卡为对象才能发动。那些卡回到墓地。'),
(79383919, 'Evil Eye Retribution', '断罪之咒眼', '断罪の呪眼', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「咒眼」怪兽存在，魔法·陷阱卡发动时才能发动。那个发动无效并破坏。自己的魔法与陷阱区域有「太阴之咒眼」存在的场合，这张卡的发动和效果不会被无效化。'),
(8775395, 'Evil Eyes Unleashed', '灾诞之咒眼', '災誕の呪眼', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「咒眼」怪兽和1张「咒眼」魔法·陷阱卡送去墓地才能发动。从卡组把1张「咒眼」装备魔法卡加入手卡。这个回合，每次自己把「咒眼」卡以外的卡的效果发动让自己失去500基本分。 ②：自己对「咒眼」连接怪兽的连接召唤成功的场合，把墓地的这张卡除外才能发动。从自己墓地选1张「咒眼」装备魔法卡给自己场上1只「咒眼」连接怪兽装备。'),
(13650422, 'Evil HERO Adusted Gold', '邪恶－英雄 黄金暗星', 'E-HERO アダスター・ゴールド', 'Effect Monster', 'Fiend', 'LIGHT', 4, 2100, 800, '这个卡名的①的效果1回合只能使用1次。 ①：把这张卡从手卡丢弃才能发动。除「邪心英雄 黯星金魔」外的1张「暗黑融合」或者有那个卡名记述的卡从卡组加入手卡。 ②：自己场上没有融合怪兽存在的场合，这张卡不能攻击。'),
(58332301, 'Evil HERO Dark Gaia', '邪恶－英雄 黑暗盖亚', 'E-HERO ダーク・ガイア', 'Fusion Monster', 'Fiend', 'EARTH', 8, -1, NULL, '恶魔族怪兽＋岩石族怪兽 这张卡用「暗黑融合」的效果才能特殊召唤。 ①：这张卡的原本攻击力变成作为这张卡的融合素材的怪兽的原本攻击力合计数值。 ②：这张卡的攻击宣言时才能发动。对方场上的守备表示怪兽全部变成表侧攻击表示。这个时候，反转怪兽的效果不发动。'),
(86282581, 'Evil HERO Darkest Knight', '邪恶－英雄 黑暗骑士', 'E-HERO ダーク・ナイト', 'Fusion Monster', 'Fiend', 'EARTH', 8, 1600, NULL, '恶魔族怪兽＋战士族怪兽 这张卡用「暗黑融合」的效果才能特殊召唤。 ①：对方场上的怪兽的攻击力下降作为这张卡的融合素材的怪兽的原本攻击力的合计数值。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。 ③：特殊召唤的表侧表示的这张卡因对方从场上离开的场合，以自己墓地1只恶魔族·战士族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(30583090, 'Evil HERO Dead-End Prison', '邪恶－英雄 死亡镜囚', 'E-HERO デス・プリズン', 'Effect Monster', 'Rock', 'LIGHT', 4, 1700, 1100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：「暗黑融合」的效果才能特殊召唤的融合怪兽在自己场上存在的场合，这张卡可以从手卡特殊召唤。 ②：从卡组把1只「英雄」怪兽送去墓地才能发动。这个回合，「英雄」融合怪兽融合召唤的场合，表侧表示的这张卡可以作为那只融合怪兽有卡名记述的1只融合素材怪兽代用（其他的融合素材不能代用）。'),
(95943058, 'Evil HERO Infernal Gainer', '邪恶－英雄 地狱掠夺者', 'E-HERO ヘル・ゲイナー', 'Effect Monster', 'Fiend', 'EARTH', 4, 1600, NULL, '①：自己主要阶段1把场上的这张卡除外，以自己场上1只恶魔族怪兽为对象才能发动。那只自己的恶魔族怪兽只要在场上表侧表示存在，同1次的战斗阶段中可以作2次攻击。 ②：这张卡为①的效果发动而被除外的场合，第2次的自己准备阶段发动。这张卡攻击表示特殊召唤。'),
(50304345, 'Evil HERO Infernal Prodigy', '邪恶－英雄 地狱顽童', 'E-HERO ヘル・ブラット', 'Effect Monster', 'Fiend', 'DARK', 2, 300, 600, '①：自己场上没有怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ②：把这张卡解放让「英雄」怪兽上级召唤成功的回合的结束阶段发动。自己从卡组抽1张。'),
(76978105, 'Evil HERO Infernal Rider', '邪恶－英雄 地狱骑士', 'E-HERO ヘル・ライダー', 'Effect Monster', 'Fiend', 'WIND', 6, 2100, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把1张「暗黑融合」加入手卡。 ②：从自己墓地把4只怪兽和这张卡除外才能发动。从卡组把1张「超融合」在自己场上盖放。直到对方回合结束时自己不是「英雄」怪兽不能特殊召唤，对用「暗黑融合」的效果才能特殊召唤的融合怪兽用那以外的效果也能融合召唤。'),
(50282757, 'Evil HERO Infernal Sniper', '邪心英雄 地狱狙魔', 'E-HERO ヘル・スナイパー', 'Fusion Monster', 'Fiend', 'FIRE', 6, 2000, 2500, '「元素英雄 黏土侠」＋「元素英雄 爆热女郎」 这张卡用「暗黑融合」的效果才能特殊召唤。 ①：这张卡只要在怪兽区域存在，不会被魔法卡的效果破坏。 ②：自己准备阶段发动。给与对方1000伤害。这个效果在这张卡在怪兽区域表侧守备表示存在的场合进行发动和处理。'),
(22160245, 'Evil HERO Inferno Wing', '邪恶－英雄 业火之翼', 'E-HERO インフェルノ・ウィング', 'Fusion Monster', 'Fiend', 'FIRE', 6, 2100, 1200, '「元素英雄 羽翼侠」＋「元素英雄 爆热女郎」 这张卡用「暗黑融合」的效果才能特殊召唤。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力和原本守备力之内较高方数值的伤害。'),
(59893882, 'Evil HERO Inferno Wing - Backfire', '邪恶－英雄 业火之翼－地狱逆火', 'E-HERO インフェルノ・ウィング－ヘルバック・ファイア', 'Fusion Monster', 'Fiend', 'FIRE', 6, 2100, 1200, '「元素英雄 羽翼侠」或「元素英雄 爆热女郎」＋「英雄」怪兽 这张卡用「暗黑融合」的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。除融合怪兽外的1张「暗黑融合」或者有那个卡名记述的卡从自己的卡组·墓地加入手卡。 ②：自己的「英雄」怪兽战斗破坏对方怪兽的场合发动。给与对方2100伤害。'),
(21947653, 'Evil HERO Lightning Golem', '邪心英雄 闪电巨魔', 'E-HERO ライトニング・ゴーレム', 'Fusion Monster', 'Fiend', 'LIGHT', 6, 2400, 1500, '「元素英雄 电光侠」＋「元素英雄 黏土侠」 这张卡用「暗黑融合」的效果才能特殊召唤。 ①：1回合1次，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(86165817, 'Evil HERO Malicious Bane', '邪恶－英雄 极恶亡魔', 'E-HERO マリシャス・ベイン', 'Fusion Monster', 'Fiend', 'DARK', 8, 3000, 3000, '「邪心英雄」怪兽＋5星以上的怪兽 这张卡用「暗黑融合」的效果才能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：场上的这张卡不会被战斗·效果破坏。 ②：自己主要阶段才能发动。持有这张卡的攻击力以下的攻击力的对方场上的怪兽全部破坏，这张卡的攻击力上升破坏的怪兽数量×200。这个效果的发动后，直到回合结束时自己不用「英雄」怪兽不能攻击宣言。'),
(58554959, 'Evil HERO Malicious Edge', '邪恶－英雄 极恶刀缘', 'E-HERO マリシャス・エッジ', 'Effect Monster', 'Fiend', 'EARTH', 7, 2600, 1800, '对方场上有怪兽存在的场合，这张卡可以把1只怪兽解放表侧表示上级召唤。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(86676862, 'Evil HERO Malicious Fiend', '邪恶－英雄 极恶邪魔', 'E-HERO マリシャス・デビル', 'Fusion Monster', 'Fiend', 'FIRE', 8, 3500, 2100, '「邪心英雄 恶刃魔」＋6星以上的恶魔族怪兽 这张卡用「暗黑融合」的效果才能特殊召唤。 ①：只要这张卡在怪兽区域存在，对方战斗阶段内，对方场上的全部怪兽变成表侧攻击表示，并在可以攻击的场合必须向这张卡作出攻击。'),
(13708888, 'Evil HERO Neos Lord', '邪恶－英雄 新宇霸主', 'E-HERO ネオス・ロード', 'Fusion Monster', 'Fiend', 'DARK', 10, 2500, 2000, '「元素英雄 新宇侠」（或者有那个卡名记述的融合怪兽）＋场上的效果怪兽 这张卡用「暗黑融合」的效果才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合或者这张卡在怪兽区域存在的状态有怪兽被送去对方墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。得到那只怪兽的控制权。 ②：场上的这张卡不会被战斗·效果破坏。'),
(45659520, 'Evil HERO Sinister Necrom', '邪恶－英雄 恶兆死灵', 'E-HERO シニスター・ネクロム', 'Effect Monster', 'Fiend', 'DARK', 5, 1600, 1800, '这个卡名的效果1回合只能使用1次。 ①：把墓地的这张卡除外才能发动。从手卡·卡组把「邪心英雄 凶灵尸魔」以外的1只「邪心英雄」怪兽特殊召唤。'),
(3598351, 'Evil HERO Toxic Bubble', '邪恶－英雄 毒命泡沫', 'E-HERO トキシック・バブル', 'Effect Monster', 'Fiend', 'WATER', 4, 800, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡特殊召唤。这个方法特殊召唤过的回合，自己不是「英雄」怪兽不能特殊召唤。 ②：这张卡特殊召唤的场合，若「暗黑融合」的效果才能特殊召唤的融合怪兽在自己场上存在则能发动。自己抽2张。'),
(35095329, 'Evil HERO Vicious Claws', '邪恶－英雄 恶意之爪', 'E-HERO ヴィシャス・クローズ', 'Effect Monster', 'Fiend', 'DARK', 7, 2500, 2500, '这个卡名的①的效果1回合只能使用1次，②的效果在决斗中只能使用1次。 ①：以场上1只「英雄」怪兽为对象才能发动。这张卡从手卡守备表示特殊召唤，作为对象的怪兽的攻击力上升300。 ②：自己场上的怪兽被战斗·效果破坏的场合才能发动。这张卡从墓地特殊召唤。那之后，自己墓地有着有「暗黑融合」的卡名记述的怪兽存在的场合，可以把场上1张卡破坏。'),
(13293158, 'Evil HERO Wild Cyclone', '邪心英雄 荒野风魔', 'E-HERO ワイルド・サイクロン', 'Fusion Monster', 'Fiend', 'EARTH', 8, 1900, 2300, '「元素英雄 荒野侠」＋「元素英雄 羽翼侠」 这张卡用「暗黑融合」的效果才能特殊召唤。 ①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：这张卡给与对方战斗伤害的场合发动。对方场上盖放的魔法·陷阱卡全部破坏。'),
(18438874, 'Evil Mind', '邪恶之心', 'イービル・マインド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有恶魔族怪兽存在的场合，可以从对方墓地的怪兽数量的以下效果选择1个发动。 ●1只以上：自己从卡组抽1张。 ●4只以上：从卡组把1只「英雄」怪兽或者1张「暗黑融合」加入手卡。 ●10只以上：从卡组把1张「融合」魔法卡加入手卡。'),
(85431040, 'Evil Thorn', '邪恶荆棘', 'イービル・ソーン', 'Effect Monster', 'Plant', 'DARK', 1, 100, 300, '①：把这张卡解放才能发动。给与对方300伤害，可以从卡组把最多2只「邪恶之棘」攻击表示特殊召唤。这个效果特殊召唤的怪兽不能把效果发动。'),
(75524093, 'Evil Token', '堕恶之爪', 'ヴィシャス・クロー', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(98360333, 'Evil★Twin Challenge', '邪恶★双子 挑战', 'Evil★Twin チャレンジ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「姬丝基勒」怪兽或「璃拉」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，以下效果可以适用。 ●进行1只「邪恶★双子」连接怪兽的连接召唤。'),
(34365442, 'Evil★Twin GG EZ', '邪恶★双子 低难度游戏', 'Evil★Twin イージーゲーム', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以把自己场上1只「姬丝基勒」怪兽或者「璃拉」怪兽解放，从以下效果选择1个发动。 ●以自己场上1只「姬丝基勒」怪兽或者「璃拉」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升解放的怪兽的原本攻击力数值。 ●要让场上的卡破坏的魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。'),
(9205573, 'Evil★Twin Ki-sikil', '邪恶★双子 姬丝吉尔', 'Evil★Twin キスキル', 'Link Monster', 'Fiend', 'LIGHT', NULL, 1100, NULL, '包含「姬丝基勒」怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，若自己场上有「璃拉」怪兽存在则能发动。自己抽1张。 ②：自己·对方的主要阶段，自己场上没有「璃拉」怪兽存在的场合才能发动。从自己墓地把1只「璃拉」怪兽特殊召唤。这个回合，自己不是恶魔族怪兽不能从额外卡组特殊召唤。'),
(6636319, 'Evil★Twin Ki-sikil Deal', '邪恶★双子 姬丝吉尔・成交', 'Evil★Twin キスキル・ディール', 'Link Monster', 'Fiend', 'LIGHT', NULL, 100, NULL, '「姬丝基勒」怪兽1只 自己对「邪恶★双子 姬丝基勒·交易」1回合只能有1次连接召唤。这个卡名的效果1回合只能使用1次。 ①：从卡组·额外卡组把1只「璃拉」怪兽送去墓地才能发动。这个回合中，以下效果适用。 ●每次对方连锁自己的「姬丝基勒」怪兽或「璃拉」怪兽的效果的发动把效果发动，自己抽1张。'),
(36609518, 'Evil★Twin Lil-la', '邪恶★双子 璃拉', 'Evil★Twin リィラ', 'Link Monster', 'Fiend', 'DARK', NULL, 1100, NULL, '包含「璃拉」怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，若自己场上有「姬丝基勒」怪兽存在，以场上1张卡为对象才能发动。那张卡破坏。 ②：自己·对方的主要阶段，自己场上没有「姬丝基勒」怪兽存在的场合才能发动。从自己墓地把1只「姬丝基勒」怪兽特殊召唤。这个回合，自己不是恶魔族怪兽不能从额外卡组特殊召唤。'),
(60759087, 'Evil★Twin Present', '邪恶★双子 馈赠', 'Evil★Twin プレゼント', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「姬丝基勒」怪兽以及「璃拉」怪兽存在的场合，可以从以下效果选择1个发动。 ●以自己场上1只「姬丝基勒」怪兽或者「璃拉」怪兽和对方场上1只表侧表示怪兽为对象才能发动。那2只怪兽的控制权交换。 ●以对方场上盖放的1张魔法·陷阱卡为对象才能发动。那张卡回到持有者卡组。'),
(93672138, 'Evil★Twin''s Trouble Sunny', '邪恶★双子 麻烦桑妮', 'Evil★Twin’s トラブル・サニー', 'Link Monster', 'Fiend', 'LIGHT', NULL, 3300, NULL, '包含「邪恶★双子」怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡解放才能发动。从自己墓地把「姬丝基勒」怪兽和「璃拉」怪兽各最多1只特殊召唤。 ②：把墓地的这张卡除外，从自己的手卡·卡组·场上（表侧表示）把1只「邪恶★双子」怪兽送去墓地才能发动。场上1张卡送去墓地。'),
(62098216, 'Evil★Twins Ki-sikil & Lil-la', '邪恶★双子 姬丝吉尔・璃拉', 'Evil★Twins キスキル・リィラ', 'Effect Monster', 'Fiend', 'DARK', 8, 2200, 2200, '这张卡不能通常召唤。把自己场上2只连接怪兽解放的场合才能从手卡·墓地特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。对方在自身场上的卡是3张以上的场合直到变成2张为止必须送去墓地。 ②：只要自己墓地有「姬丝基勒」怪兽以及「璃拉」怪兽存在，这张卡的攻击力·守备力上升2200。'),
(42679662, 'Evilswarm Azzathoth', '入魔浑沌 阿撒托斯', 'ヴェルズ・アザトホース', 'Flip Effect Monster', 'Reptile', 'DARK', 4, 750, 1950, '反转：选择场上1只特殊召唤的怪兽回到持有者卡组。'),
(36757171, 'Evilswarm Bahamut', '入魔龙王 巴哈姆特', 'ヴェルズ・バハムート', 'XYZ Monster', 'Dragon', 'DARK', 4, 2350, 1350, '名字带有「入魔」的4星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择对方场上表侧表示存在的1只怪兽才能发动。从手卡丢弃1只名字带有「入魔」的怪兽，得到选择的对方怪兽的控制权。'),
(79785958, 'Evilswarm Castor', '入魔鬼·北河二', 'ヴェルズ・カストル', 'Effect Monster', 'Warrior', 'DARK', 4, 1750, 550, '这张卡召唤成功的回合，自己在通常召唤外加上只有1次可以把1只名字带有「入魔」的怪兽召唤。'),
(77841719, 'Evilswarm Coppelia', '入魔人偶 葛佩利亚', 'ヴェルズ・コッペリアル', 'Effect Monster', 'Machine', 'DARK', 6, 2450, 2050, '这张卡不能特殊召唤。这张卡因对方从场上离开时，选择对方场上表侧表示存在的1只怪兽直到下次的自己的结束阶段时得到控制权。'),
(46772449, 'Evilswarm Exciton Knight', '励辉士 邪蚀西卜', '励輝士 ヴェルズビュート', 'XYZ Monster', 'Fiend', 'LIGHT', 4, 1900, NULL, '4星怪兽×2 ①：自己主要阶段以及对方战斗阶段，对方的手卡·场上的卡数量比自己的手卡·场上的卡数量多的场合，把这张卡1个超量素材取除才能发动（同一连锁上最多1次）。场上的其他卡全部破坏。这个效果的发动后，直到回合结束时对方受到的全部伤害变成0。'),
(31456110, 'Evilswarm Golem', '入魔巨偶虫', 'ヴェルズ・ゴーレム', 'Effect Monster', 'Rock', 'DARK', 5, 2150, 1250, '1回合1次，可以选择场上表侧表示存在的1只暗属性以外的5星以上的怪兽破坏。'),
(77542832, 'Evilswarm Heliotrope', '入魔鬼·血石', 'ヴェルズ・ヘリオロープ', 'Normal Monster', 'Rock', 'DARK', 4, 1950, 650, '求所无别　结终　灭破　坏破　念邪的高崇　鬼魔入侵　魂之辈我　恶邪为又　粹纯为既'),
(35209994, 'Evilswarm Hraesvelg', '入魔巨鹰 赫拉斯', 'ヴェルズ・フレイス', 'Flip Effect Monster', 'Winged Beast', 'DARK', 4, 1150, 1850, '反转：选择对方场上表侧表示存在的1张卡回到持有者手卡。'),
(4756629, 'Evilswarm Kerykeion', '入魔双蛇杖使', 'ヴェルズ・ケルキオン', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1600, 1550, '这个卡名的①②③的效果1回合各能使用1次。 ①：把自己墓地1只「入魔」怪兽除外，以自己墓地1只「入魔」怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡的①的效果适用的回合的主要阶段才能发动。把1只「入魔」怪兽召唤。 ③：这张卡被送去墓地的回合，「入魔」怪兽召唤的场合需要的解放可以减少1只。'),
(40921545, 'Evilswarm Ketos', '入魔鲸人', 'ヴェルズ・カイトス', 'Effect Monster', 'Aqua', 'DARK', 4, 1750, 1050, '把这张卡解放发动。选择对方场上存在的1张魔法·陷阱卡破坏。'),
(8814959, 'Evilswarm Mandragora', '邪蚀曼德拉草', 'ヴェルズ・マンドラゴ', 'Effect Monster', 'Plant', 'DARK', 4, 1550, 1450, '①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以从手卡特殊召唤。'),
(359563, 'Evilswarm Nightmare', '邪蚀梦魇', 'ヴェルズ・ナイトメア', 'XYZ Monster', 'Fiend', 'DARK', 4, 950, 1950, '暗属性4星怪兽×2 ①：对方把怪兽特殊召唤时，把这张卡1个超量素材取除才能发动。那些怪兽变成里侧守备表示。'),
(72429240, 'Evilswarm O''lantern', '入魔鬼灯人', 'ヴェルズ・オランタ', 'Effect Monster', 'Pyro', 'DARK', 4, 1650, 1250, '把这张卡解放发动。选择对方场上表侧表示存在的1只怪兽破坏。'),
(5284653, 'Evilswarm Obliviwisp', '入魔鬼火', 'ヴェルズ・オ・ウィスプ', 'Effect Monster', 'Pyro', 'DARK', 4, 450, 2050, '和这张卡进行战斗的效果怪兽的效果在伤害计算后无效化。'),
(91279700, 'Evilswarm Ophion', '入魔龙主 俄菲翁', 'ヴェルズ・オピオン', 'XYZ Monster', 'Dragon', 'DARK', 4, 2550, 1650, '4星「入魔」怪兽×2 ①：只要持有超量素材的这张卡在怪兽区域存在，双方不能把5星以上的怪兽特殊召唤。 ②：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1张「侵略的」魔法·陷阱卡加入手卡。'),
(38273745, 'Evilswarm Ouroboros', '入魔邪龙 乌洛波洛斯', 'ヴェルズ・ウロボロス', 'XYZ Monster', 'Dragon', 'DARK', 4, 2750, 1950, '4星怪兽×3 1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。以下效果只在这张卡在场上表侧表示存在各能选择1次。 ●选择对方场上存在的1张卡回到持有者手卡。 ●对方手卡随机选1张送去墓地。 ●选择对方墓地存在的1张卡从游戏中除外。'),
(4058065, 'Evilswarm Salamandra', '邪蚀沙罗曼龙', 'ヴェルズ・サラマンドラ', 'Effect Monster', 'Dinosaur', 'DARK', 4, 1850, 950, '①：从自己墓地把1只怪兽除外才能发动。这张卡的攻击力直到对方回合结束时上升300。这个效果1回合可以使用最多2次。'),
(65884091, 'Evilswarm Thanatos', '入魔死神 塔那托斯', 'ヴェルズ・タナトス', 'XYZ Monster', 'Fiend', 'DARK', 4, 2350, 1350, '暗属性4星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。这个回合，这张卡不受这张卡以外的怪兽的效果影响。这个效果在对方回合也能发动。'),
(78663366, 'Evilswarm Thunderbird', '入魔雷神鸟', 'ヴェルズ・サンダーバード', 'Effect Monster', 'Thunder', 'DARK', 4, 1650, 1050, '魔法·陷阱·效果怪兽的效果发动时，可以把自己场上的这张卡从游戏中除外。这个效果在对方回合也能发动。这个效果除外的这张卡在下次的准备阶段时回到场上，攻击力上升300。「入魔雷神鸟」的效果1回合只能发动1次。'),
(3536537, 'Evilswarm Zahak', '入魔妖龙 扎哈克', 'ヴェルズ・ザッハーク', 'Effect Monster', 'Dragon', 'DARK', 4, 1850, 850, '①：场上的表侧表示的这张卡被对方破坏送去墓地的场合，以场上1只特殊召唤的5星以上的怪兽为对象发动。那只5星以上的怪兽破坏。'),
(64815084, 'Evo-Branch', '进化的分歧点', '進化の分岐点', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只爬虫类族怪兽发动。选择的怪兽破坏，从卡组把1只名字带有「进化虫」的怪兽里侧守备表示特殊召唤。'),
(88760522, 'Evo-Diversity', '多样进化', '多様進化', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组把1只名字带有「进化虫」或者「进化龙」的怪兽加入手卡。「多样进化」在1回合只能发动1张。'),
(5338223, 'Evo-Force', '强制进化', '強制進化', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只名字带有「进化虫」的怪兽解放发动。从卡组把1只名字带有「进化龙」的怪兽特殊召唤。这个效果特殊召唤的怪兽变成当作用名字带有「进化虫」的怪兽的效果特殊召唤使用。'),
(24362891, 'Evo-Instant', '突然进化', '突然進化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只爬虫类族怪兽解放才能发动。从卡组把1只名字带有「进化龙」的怪兽特殊召唤。'),
(8632967, 'Evo-Karma', '进化的宿命', '進化の宿命', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的名字带有「进化虫」的怪兽的效果让怪兽特殊召唤成功时，对方不能把魔法·陷阱·效果怪兽的效果发动。'),
(34026662, 'Evo-Miracle', '进化的奇迹', '進化の奇跡', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择名字带有「进化虫」的怪兽的效果特殊召唤的1只怪兽发动。这个回合，选择的怪兽不会被战斗以及卡的效果破坏。'),
(14154221, 'Evo-Price', '进化的代偿', '進化の代償', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '名字带有「进化虫」的怪兽的效果让怪兽特殊召唤的场合，可以选择场上1张卡破坏。这个效果1回合只能使用1次。'),
(74100225, 'Evo-Singularity', '进化的特异点', '進化の特異点', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「进化虫」怪兽和1只「进化龙」怪兽为对象才能发动。从额外卡组把1只「进化帝」超量怪兽特殊召唤，把作为对象的怪兽作为那只超量怪兽的超量素材。'),
(96872283, 'Evocator Chevalier', '真化护法 骑士', 'エヴォルテクター シュバリエ', 'Gemini Monster', 'Warrior', 'FIRE', 4, 1900, 900, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●把自己场上1张表侧表示的装备卡送去墓地，以对方场上1张卡为对象才能发动。那张对方的卡破坏。'),
(16146511, 'Evocator Eveque', '真化护法 主教', 'エヴォルテクター エヴェック', 'Gemini Monster', 'Warrior', 'FIRE', 4, 1500, 1000, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡召唤·特殊召唤成功的场合，以「真化护法 主教」以外的自己墓地1只战士族·炎属性怪兽或者二重怪兽为对象才能发动。那只怪兽特殊召唤。这个卡名的这个效果1回合只能使用1次。'),
(80651316, 'Evolsaur Cerato', '进化龙・角鼻龙', 'エヴォルダー・ケラト', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1900, 1400, '这张卡用名字带有「进化虫」的怪兽的效果特殊召唤成功时，这张卡的攻击力上升200。那之后，这张卡战斗破坏对方怪兽的场合，可以从自己卡组把1只名字带有「进化虫」的怪兽加入手卡。'),
(39672388, 'Evolsaur Darwino', '进化龙·达尔文翼龙', 'エヴォルダー・ダルウィノス', 'Effect Monster', 'Dinosaur', 'FIRE', 5, 2200, 700, '这张卡用名字带有「进化虫」的怪兽的效果特殊召唤成功时，可以选择场上表侧表示存在的1只怪兽等级上升最多2星。'),
(17045014, 'Evolsaur Diplo', '进化龙・梁龙', 'エヴォルダー・ディプロドクス', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1600, 800, '这张卡用名字带有「进化虫」的怪兽的效果特殊召唤成功时，选择对方场上存在的1张魔法·陷阱卡破坏。'),
(23234094, 'Evolsaur Elias', '进化龙・双腔龙', 'エヴォルダー・エリアス', 'Effect Monster', 'Dinosaur', 'FIRE', 6, 100, 2400, '这张卡用名字带有「进化虫」的怪兽的效果特殊召唤成功时，可以从手卡把1只恐龙族·炎属性·6星以下的怪兽特殊召唤。'),
(15171722, 'Evolsaur Lios', '进化龙・滑齿龙', 'エヴォルダー・リオス', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1600, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「通向进化的吊桥」或「进化的特异点」在自己场上盖放。 ②：这张卡是已召唤或者已用炎属性怪兽的效果特殊召唤的场合，自己主要阶段才能发动。从卡组把1只爬虫类族·恐龙族的炎属性怪兽送去墓地。那之后，可以把场上2只怪兽的种族和等级变成和送去墓地的怪兽相同。'),
(16480084, 'Evolsaur Pelta', '进化龙·蜥结龙', 'エヴォルダー・ペルタ', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1100, 2000, '这张卡用名字带有「进化虫」的怪兽的效果特殊召唤成功时，这张卡的守备力上升500。那之后，这张卡被战斗破坏的场合，可以从卡组把1只名字带有「进化虫」的怪兽加入手卡。'),
(69633792, 'Evolsaur Terias', '进化龙·依潘龙', 'エヴォルダー・テリアス', 'Effect Monster', 'Dinosaur', 'FIRE', 6, 2400, 600, '这张卡用名字带有「进化虫」的怪兽的效果特殊召唤成功时，这张卡的攻击力下降500。'),
(54266211, 'Evolsaur Vulcano', '进化龙・火山齿龙', 'エヴォルダー・ウルカノドン', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1200, 1000, '这张卡用名字带有「进化虫」的怪兽的效果特殊召唤成功时，可以选择自己墓地存在的1只名字带有「进化龙」的怪兽特殊召唤。这个效果特殊召唤的怪兽不能攻击宣言。'),
(56240989, 'Evoltile Casinerio', '进化虫・羊膜祖蜥', 'エヴォルド・カシネリア', 'Effect Monster', 'Reptile', 'FIRE', 3, 1600, 400, '这张卡战斗破坏对方怪兽的战斗阶段结束时，把这张卡解放才能发动。从卡组把2只恐龙族·炎属性·6星以下的同名怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段时从游戏中除外。'),
(91903221, 'Evoltile Elginero', '进化虫・埃尔金螈', 'エヴォルド・エルギネル', 'Effect Monster', 'Reptile', 'FIRE', 2, NULL, NULL, '场上的这张卡被解放送去墓地时，从卡组抽1张卡。那之后，可以让手卡1只恐龙族怪兽回到卡组，从卡组把1只名字带有「进化虫」的怪兽加入手卡。'),
(55488859, 'Evoltile Gephyro', '进化虫·桥蜥', 'エヴォルド・ゲフィロス', 'Effect Monster', 'Reptile', 'FIRE', 1, 200, 400, '这张卡被战斗破坏送去墓地时，可以选择自己墓地存在的1只名字带有「进化龙」的怪兽特殊召唤。'),
(3283679, 'Evoltile Lagosucho', '进化虫・兔鳄', 'エヴォルド・ラゴスクス', 'Effect Monster', 'Reptile', 'FIRE', 3, 1200, 500, '这张卡召唤成功时，可以从卡组把1只名字带有「进化龙」的怪兽送去墓地。此外，这张卡反转时，可以从卡组把1只名字带有「进化虫」的怪兽特殊召唤。'),
(13046291, 'Evoltile Megachirella', '进化虫・巨手蜥', 'エヴォルド・メガキレラ', 'Effect Monster', 'Reptile', 'FIRE', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只爬虫类族怪兽解放，丢弃1张手卡才能发动。从卡组把1只6星以下的恐龙族·炎属性怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只没有超量素材的龙族超量怪兽为对象才能发动。从自己的手卡·墓地选最多2只爬虫类族·恐龙族的怪兽在作为对象的怪兽下面重叠作为超量素材（同名卡最多1张）。'),
(88095331, 'Evoltile Najasho', '进化虫・纳哈什蛇', 'エヴォルド・ナハシュ', 'Effect Monster', 'Reptile', 'FIRE', 2, 100, 2000, '场上的这张卡被解放的场合，可以从卡组把1只名字带有「进化龙」的怪兽特殊召唤。'),
(28877602, 'Evoltile Odonto', '进化虫・半甲齿龟', 'エヴォルド・オドケリス', 'Effect Monster', 'Reptile', 'FIRE', 2, 500, 1200, '这张卡召唤成功时，可以从手卡把1只名字带有「进化龙」的怪兽特殊召唤。'),
(89776023, 'Evoltile Pholis', '进化虫・棱角鳞鳄', 'エヴォルド・フォリス', 'Effect Monster', 'Reptile', 'FIRE', 2, 900, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的手卡·墓地把1只「进化虫」怪兽里侧守备表示特殊召唤。 ②：自己主要阶段才能发动。从卡组把1张「强制进化」或「突然进化」在自己场上盖放。 ③：自己场上的怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1只爬虫类族·恐龙族怪兽解放。'),
(20855340, 'Evoltile Pleuro', '进化虫·侧喙头蜥', 'エヴォルド・プレウロス', 'Effect Monster', 'Reptile', 'FIRE', 1, 200, 200, '这张卡在自己场上被破坏送去墓地的场合，可以从手卡把1只名字带有「进化龙」的怪兽特殊召唤。'),
(81873903, 'Evoltile Westlo', '进化虫・西洛仙蜥', 'エヴォルド・ウェストロ', 'Flip Effect Monster', 'Reptile', 'FIRE', 3, 700, 1900, '反转：从自己卡组把1只名字带有「进化龙」的怪兽特殊召唤。'),
(52875873, 'Evolution Burst', '进化冲击波', 'エヴォリューション・バースト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有「电子龙」表侧表示存在的场合才能发动。对方场上1张卡破坏。这张卡发动的回合「电子龙」不能攻击。'),
(78217065, 'Evolution End Burst', '进化终末冲击波', 'エヴォリューション・レザルト・バースト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张「超载融合」加入手卡。这个回合中，「超载融合」的效果用6只以上的怪兽为素材作融合召唤的场合，那只怪兽在这个回合在同1次的战斗阶段中可以作出最多有那些作为融合素材的怪兽数量的攻击。这张卡的发动后，直到回合结束时自己不用魔法卡的效果不能把怪兽特殊召唤。'),
(93504463, 'Evolutionary Bridge', '通往进化的桥梁', '進化への懸け橋', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽被选择作为攻击对象时才能发动。选择自己墓地存在的1只名字带有「进化虫」的怪兽特殊召唤，把攻击对象转换为那只怪兽进行伤害计算。'),
(42752141, 'Evolzar Dolkka', '进化帝・长鳄龙', 'エヴォルカイザー・ドルカ', 'XYZ Monster', 'Dragon', 'FIRE', 4, 2300, 1700, '恐龙族4星怪兽×2 ①：这张卡以外的怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(74294676, 'Evolzar Laggia', '进化帝・半鸟龙', 'エヴォルカイザー・ラギア', 'XYZ Monster', 'Dragon', 'FIRE', 4, 2400, 2000, '恐龙族4星怪兽×2 ①：可以把这张卡2个超量素材取除，以下效果发动。 ●魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ●自己或对方把怪兽召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。'),
(35103106, 'Evolzar Lars', '进化帝・沧怒龙', 'エヴォルカイザー・ラーズ', 'XYZ Monster', 'Dragon', 'FIRE', 6, 2500, 1500, '6星怪兽×2 ①：对方不能把持有超量素材的这张卡作为怪兽的效果的对象。 ②：对方把卡的效果发动时，把这张卡2个超量素材取除，以对方场上1张表侧表示卡为对象才能发动（这张卡只有爬虫类族·恐龙族怪兽在作为超量素材的场合，取除的超量素材数量可以变成1个）。那张卡的效果直到回合结束时无效。'),
(18511599, 'Evolzar Solda', '进化帝・鬼翼龙', 'エヴォルカイザー・ソルデ', 'XYZ Monster', 'Dragon', 'FIRE', 6, 2600, 1000, '恐龙族6星怪兽×2 ①：持有超量素材的这张卡不会被效果破坏。 ②：对方对怪兽的特殊召唤成功时，把这张卡1个超量素材取除才能发动。那些怪兽破坏。'),
(53180020, 'Exa, Enforcer of the Nekroz', '影灵衣的战士 艾格扎', '影霊衣の戦士 エグザ', 'Effect Monster', 'Dragon', 'WATER', 5, 2000, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡被效果解放的场合才能发动。从卡组把1只龙族「影灵衣」仪式怪兽加入手卡。 ②：这张卡被除外的场合，以自己的除外状态的1只其他的「影灵衣」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(63749102, 'Exarion Universe', '宇宙人马兽', 'イグザリオン・ユニバース', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1800, 1900, '①：这张卡向守备表示怪兽攻击的战斗步骤才能发动。直到回合结束时，这张卡的攻击力下降400，这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(92812851, 'Exceed the Pendulum', '超升灵摆・奇迹的魔剑士', '奇跡の魔導剣士', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 2000, NULL, '包含灵摆怪兽的效果怪兽2只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从自己的额外卡组（表侧）把1只灵摆怪兽加入手卡。 ②：这张卡的攻击力上升自己场上的灵摆怪兽卡数量×100。 ③：自己·对方的主要阶段才能发动。把持有用自己的灵摆区域2张卡的灵摆刻度可以灵摆召唤的等级的1只灵摆怪兽从自己的手卡·墓地守备表示特殊召唤。'),
(52782439, 'Exceptional Schedule', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(5556668, 'Exchange', '手札对换', 'エクスチェンジ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '双方玩家把手卡公开，各自选1张对方的卡加入自己手卡。'),
(25209168, 'Exchange of Despair and Hope', '绝望与希望的逆转', '絶望と希望の逆転', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有天使族·地属性怪兽3只以上存在的场合才能发动。场上的怪兽全部送去墓地。那之后，双方可以从对方墓地选最多有被这个效果各送去对方墓地的怪兽数量的怪兽在自身场上特殊召唤。自己墓地有「现世与冥界的逆转」存在的场合，再让自己可以从卡组选1张陷阱卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(3160805, 'Exchange of Night and Day', '明与宵的逆转', '明と宵の逆転', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '可以从以下效果选择1个发动。「明与宵的逆转」的效果1回合只能使用1次。 ●从手卡把1只战士族·光属性怪兽送去墓地。那之后，和那只怪兽相同等级的1只战士族·暗属性怪兽从卡组加入手卡。 ●从手卡把1只战士族·暗属性怪兽送去墓地。那之后，和那只怪兽相同等级的1只战士族·光属性怪兽从卡组加入手卡。'),
(17484499, 'Exchange of the Spirit', '现世与冥界的逆转', '現世と冥界の逆転', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在决斗中只能发动1张。 ①：双方墓地的卡各自是15张以上的场合支付1000基本分才能发动。双方玩家各自把自身的卡组和墓地的卡全部交换，那之后卡组洗切。'),
(40669071, 'Excode Talker', '特码语者', 'エクスコード・トーカー', 'Link Monster', 'Cyberse', 'WIND', NULL, 2300, NULL, '电子界族怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功时，指定额外怪兽区域的怪兽数量的没有使用的主要怪兽区域才能发动。指定的区域在这只怪兽表侧表示存在期间不能使用。 ②：这张卡所连接区的怪兽攻击力上升500，不会被效果破坏。'),
(20419926, 'Execute Protocols', '枪王处决', 'ガンスリンガー・エクスキューション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的战斗阶段，从自己墓地把1只暗属性连接怪兽除外，以自己场上1只「枪管」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升因为这张卡发动而除外的怪兽的攻击力数值。'),
(55976207, 'Execution of the Contract', '契约遂行', '契約の遂行', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只仪式怪兽给对方观看才能发动。装备怪兽的等级直到回合结束时变成和给人观看的怪兽的等级相同。 ②：装备怪兽被解放让这张卡被送去墓地的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(95451366, 'Exhausting Spell', '魔力枯竭', '魔力枯渇', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '将自己与对方场上存在的所有魔力指示物全部除去。'),
(26725158, 'Exile of the Wicked', '恶魔祓除', '悪魔払い', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上的恶魔族怪兽全部破坏。'),
(74131780, 'Exiled Force', '流氓佣兵部队', 'ならず者傭兵部隊', 'Effect Monster', 'Warrior', 'EARTH', 4, 1000, 1000, '①：把这张卡解放，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(12600382, 'Exodia Necross', '艾克佐迪亚的亡灵', 'エクゾディア・ネクロス', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, NULL, '这张卡不能通常召唤。「与艾克佐迪亚的契约」的效果才能特殊召唤。 ①：这张卡不会被战斗以及魔法·陷阱卡的效果破坏。 ②：自己准备阶段发动。这张卡的攻击力上升500。 ③：自己墓地是「被封印的艾克佐迪亚」「被封印者的右腕」「被封印者的左腕」「被封印者的右足」「被封印者的左足」的其中任意种不存在的场合这张卡破坏。'),
(33396948, 'Exodia the Forbidden One', '被封印的艾克佐迪亚', '封印されしエクゾディア', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1000, 1000, '这张卡和「被封印者的右腕」「被封印者的左腕」「被封印者的右足」「被封印者的左足」在手卡全部齐集时，自己决斗胜利。'),
(5008836, 'Exodia, the Legendary Defender', '守护神 艾克佐迪亚', '守護神エクゾディア', 'Effect Monster', 'Spellcaster', 'DARK', 10, -1, -1, '这张卡不能特殊召唤。这张卡的①的方法召唤的这张卡战斗破坏原本持有者是对方的恶魔族·暗属性怪兽时，自己决斗胜利。 ①：这张卡也能把5只怪兽解放作召唤。 ②：这张卡的攻击力·守备力变成因为这张卡召唤而解放的怪兽的原本的攻击力·守备力各自合计数值。'),
(13893596, 'Exodius the Ultimate Forbidden Lord', '究极封印神 艾克佐迪奥斯', '究極封印神エクゾディオス', 'Effect Monster', 'Spellcaster', 'DARK', 10, -1, NULL, '这张卡不能通常召唤。让自己墓地的怪兽全部回到卡组·额外卡组的场合才能特殊召唤。这张卡的②的效果让「被封印」怪兽5种类被送去自己墓地全部齐集时，自己决斗胜利。 ①：这张卡的攻击力上升自己墓地的通常怪兽数量×1000。 ②：这张卡的攻击宣言时发动。从手卡·卡组把1只怪兽送去墓地。 ③：表侧表示的这张卡从场上离开的场合除外。'),
(4408198, 'Exosister Arment', '驱魔姐妹・诚愿武装', 'エクソシスター・アーメント', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，从墓地特殊召唤的怪兽不在对方场上存在的场合，不在对方回合不能发动。 ①：支付800基本分，以自己场上1只「救祓少女」怪兽为对象才能发动。同名卡不在自己场上存在的1只「救祓少女」超量怪兽在作为对象的自己怪兽上面重叠当作超量召唤从额外卡组特殊召唤。'),
(41524885, 'Exosister Asophiel', '驱魔姐妹・阿索菲尔', 'エクソシスター・アソフィール', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2100, 1800, '4星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡用「救祓少女」怪兽为素材作超量召唤的场合才能发动。这个回合，双方不能把墓地的卡的效果发动。 ②：场上的这张卡不会被从墓地特殊召唤的怪兽发动的效果破坏。 ③：把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽回到手卡。'),
(52335937, 'Exosister Betrayal', '驱魔姐妹・圣母悼歌', 'エクソシスター・バト・マーテル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：作为这张卡的发动时的效果处理，以下效果适用。 ●从卡组把2只「救祓少女」怪兽加入手卡。那之后，选自己1张手卡丢弃。 ②：以自己场上1只表侧表示怪兽为对象才能发动。进行1只在那只怪兽有卡名记述的「救祓少女」怪兽的召唤。 ③：怪兽被送去对方墓地的场合才能发动（伤害步骤也能发动）。对方把那之内的1只除外。'),
(30802207, 'Exosister Carpedivem', '驱魔姐妹・惜取魔鬼', 'エクソシスター・カルペディベル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：双方不能把自己场上的「救祓少女」怪兽作为从墓地特殊召唤的怪兽的效果的对象。 ②：自己把「救祓少女」怪兽超量召唤的场合，宣言1个卡名才能发动。直到回合结束时，原本卡名和宣言的卡相同的卡的效果无效化。 ③：自己的「救祓少女」怪兽进行战斗的攻击宣言时，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(16474916, 'Exosister Elis', '驱魔姐妹・以利斯', 'エクソシスター・エリス', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 500, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「救祓少女」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。自己场上有「救祓少女·斯特拉」存在的场合，再让自己回复800基本分。 ②：对方让自己或对方的卡从墓地离开的场合才能发动。把1只「救祓少女」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。'),
(5530780, 'Exosister Gibrine', '驱魔姐妹・吉卜利努', 'エクソシスター・ジブリーヌ', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 1400, 2800, '4星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡用「救祓少女」怪兽为素材作超量召唤的自己·对方回合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。 ②：场上的这张卡不会被从墓地特殊召唤的怪兽发动的效果破坏。 ③：把这张卡1个超量素材取除才能发动。这个回合中，自己场上的超量怪兽的攻击力上升800。'),
(79858629, 'Exosister Irene', '驱魔姐妹・怡莱努', 'エクソシスター・イレーヌ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 400, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡让1张「救祓少女」卡回到卡组最下面才能发动。自己抽1张。自己场上有「救祓少女·索菲娅」存在的场合，再让自己回复800基本分。 ②：对方让自己或对方的卡从墓地离开的场合才能发动。把1只「救祓少女」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。'),
(77675029, 'Exosister Karmael', '驱魔姐妹・卡尔玛尔', 'エクソシスター・カルマエル', 'XYZ Monster', 'Fairy', 'DARK', 4, 2600, 1800, '4星「救祓少女」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。这个回合的结束阶段，自己的卡组·墓地·除外状态的1张「救祓少女」魔法·陷阱卡在自己场上盖放。 ②：对方把怪兽的效果·通常魔法·通常陷阱卡发动时才能发动。这张卡的超量素材全部取除，那个效果变成「从对方墓地把1张卡加入对方手卡」。'),
(78135071, 'Exosister Kaspitell', '驱魔姐妹・加斯伯特拉', 'エクソシスター・カスピテル', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2300, 800, '4星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡用「救祓少女」怪兽为素材作超量召唤的场合才能发动。这个回合，双方不能从墓地把怪兽特殊召唤。 ②：这张卡不会被和从墓地特殊召唤的怪兽的战斗破坏。 ③：把这张卡1个超量素材取除才能发动。从卡组把1只「救祓少女」怪兽加入手卡。'),
(37343995, 'Exosister Martha', '驱魔姐妹・玛尔法', 'エクソシスター・マルファ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有超量怪兽的场合才能发动（这个效果发动的回合，自己不是「救祓少女」怪兽不能特殊召唤）。这张卡从手卡特殊召唤，从卡组把1只「救祓少女·埃莉丝」特殊召唤。 ②：自己或对方的卡从墓地离开的场合才能发动。把1只「救祓少女」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。'),
(42741437, 'Exosister Mikailis', '驱魔姐妹・米迦以利斯', 'エクソシスター・ミカエリス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 1800, '4星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡用「救祓少女」怪兽为素材作超量召唤的自己·对方回合，以对方的场上·墓地1张卡为对象才能发动。那张卡除外。 ②：这张卡不会被和从墓地特殊召唤的怪兽的战斗破坏。 ③：把这张卡1个超量素材取除才能发动。从卡组把1张「救祓少女」魔法·陷阱卡加入手卡。'),
(77913594, 'Exosister Pax', '驱魔姐妹・平安同在', 'エクソシスター・パークス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，支付800基本分才能发动。从卡组把「救祓少女和平问候」以外的1张「救祓少女」卡加入手卡。这个效果把怪兽加入手卡，有在那只怪兽有卡名记述的「救祓少女」怪兽在自己的场上或墓地存在的场合，可以再把加入手卡的那只怪兽特殊召唤。'),
(197042, 'Exosister Returnia', '驱魔姐妹・连祷', 'エクソシスター・リタニア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽只有「救祓少女」怪兽的场合，支付800基本分，以对方的场上·墓地1张卡为对象才能发动。那张卡除外。那之后，可以从以下效果选1个适用。 ●进行1只「救祓少女」超量怪兽的超量召唤。 ●这个回合自己是已把怪兽超量召唤的场合，对方场上1张卡除外。'),
(5352328, 'Exosister Sophia', '驱魔姐妹・索菲亚', 'エクソシスター・ソフィア', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 100, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有其他的「救祓少女」怪兽存在的场合才能发动。自己抽1张。自己场上有「救祓少女·伊雷娜」存在的场合，再让自己回复800基本分。 ②：对方让自己或对方的卡从墓地离开的场合才能发动。把1只「救祓少女」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。'),
(43863925, 'Exosister Stella', '驱魔姐妹・斯特拉', 'エクソシスター・ステラ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 300, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只「救祓少女」怪兽特殊召唤。那之后，自己场上有「救祓少女·埃莉丝」存在的场合，自己回复800基本分。 ②：对方让自己或对方的卡从墓地离开的场合才能发动。把1只「救祓少女」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。'),
(77891946, 'Exosister Vadis', '驱魔姐妹・去往何处', 'エクソシスター・バディス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付800基本分才能发动。从卡组选1只「救祓少女」怪兽，再从卡组选1只在那只怪兽有卡名记述的「救祓少女」怪兽。那2只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到卡组。这张卡的发动后，直到回合结束时自己不是「救祓少女」怪兽不能从额外卡组特殊召唤。'),
(59242457, 'Exosisters Magnifica', '驱魔姐妹双姝・圣母颂歌', 'エクソシスターズ・マニフィカ', 'XYZ Monster', 'Warrior', 'LIGHT', 8, 2800, 2800, '4阶「救祓少女」超量怪兽×2 这张卡用以上记的卡为超量素材的超量召唤才能特殊召唤。 ①：这张卡在同1次的战斗阶段中可以作2次攻击。 ②：自己·对方回合1次，把这张卡1个超量素材取除才能发动。对方场上1张卡除外。 ③：对方把效果发动时才能发动（同一连锁上最多1次）。给这张卡作为超量素材中的1只自己的超量怪兽回到额外卡组。那之后，可以把那只怪兽在自己场上的这张卡上面重叠当作超量召唤作特殊召唤。'),
(84125619, 'Expendable Dai', '粗人对刺', '刺し違GUY', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只战士族怪兽解放，以场上1张卡为对象才能发动。那张卡破坏，自己从卡组抽1张。'),
(20586572, 'Exploder Dragon', '轰炸龙', 'ボマー・ドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 3, 1000, NULL, '①：这张卡的攻击发生的双方的战斗伤害变成0。 ②：这张卡被战斗破坏送去墓地的场合发动。把让这张卡破坏的怪兽破坏。'),
(40529384, 'Exploder Dragonwing', '爆翼龙', 'エクスプロード・ウィング・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 7, 2400, 1600, '调整＋调整以外的龙族怪兽1只以上 和持有这张卡的攻击力以下的攻击力的场上表侧表示存在的怪兽进行战斗的场合，可以不进行伤害计算把那只怪兽破坏，给与对方基本分破坏怪兽的攻击力数值的伤害。'),
(31353051, 'Exploderokket Dragon', '炸裂枪弹龙', 'エクスプロードヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 2000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，双方受到2000伤害。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「爆炸弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(33413279, 'Explosive Magician', '爆破魔术师', 'エクスプローシブ・マジシャン', 'Synchro Monster', 'Spellcaster', 'LIGHT', 6, 2500, 1800, '调整＋调整以外的魔法师族怪兽1只以上 可以把自己场上存在的2个魔力指示物取除，选择对方场上存在的1张魔法·陷阱卡破坏。'),
(52140003, 'Explosive Urchin', '爆弹海胆', '爆弾ウニ－ボム・アーチン－', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方把陷阱卡发动时才能发动。自己的准备阶段时，对方场上有陷阱卡表侧表示存在的场合，给与对方基本分1000分伤害。发动后第3次的自己的结束阶段时这张卡送去墓地。'),
(38210374, 'Explossum', '爆貘团', 'バク団', 'Effect Monster', 'Beast', 'EARTH', 1, 100, 100, '自己的主要阶段时，手卡或者自己场上的这只怪兽可以当作装备卡使用给对方场上1只超量怪兽装备。用这个效果把这张卡装备的怪兽没有超量素材的场合，那只怪兽破坏。此外，这张卡当作装备卡使用而装备中的场合，每次对方的准备阶段把装备怪兽1个超量素材取除。'),
(7080743, 'Express Train Trolley Olley', '豪腕特急 矿车火车头', '豪腕特急トロッコロッコ', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 1000, '①：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这次超量召唤成功的场合发动。这张卡的攻击力上升800。'),
(984114, 'Expressroid', '特快机人', 'エクスプレスロイド', 'Effect Monster', 'Machine', 'EARTH', 4, 400, 1600, '①：这张卡召唤·反转召唤·特殊召唤成功时，以「特快机人」以外的自己墓地2只「机人」怪兽为对象才能发动。那些怪兽加入手卡。'),
(51822687, 'Expurrely Happiness', '爱克斯皮尔莉・幸福', 'エクスピュアリィ・ハピネス', 'XYZ Monster', 'Fairy', 'LIGHT', 7, 2500, 1100, '7星怪兽×2 这张卡也能在持有超量素材5个以上的自己的2阶怪兽上面重叠来超量召唤。 ①：自己主要阶段才能发动。这张卡1个超量素材取除，对方场上的全部表侧表示怪兽的效果直到回合结束时无效。这张卡有1星「纯爱妖精」怪兽在作为超量素材的场合，对方不能对应这个效果的发动把效果发动。 ②：持有超量素材5个以上的这张卡进行战斗的攻击宣言时发动。给与对方1500伤害。'),
(83827392, 'Expurrely Noir', '爱克斯皮尔莉・黑夜', 'エクスピュアリィ・ノアール', 'XYZ Monster', 'Fairy', 'DARK', 7, 1100, 2800, '7星怪兽×2 这张卡也能在持有超量素材5个以上的自己的2阶怪兽上面重叠来超量召唤。 ①：持有超量素材5个以上的这张卡不受对方发动的效果影响。 ②：把这张卡2个超量素材取除，以对方的场上·墓地1张卡为对象才能发动。那张卡回到持有者卡组最下面。这张卡有1星「纯爱妖精」怪兽在作为超量素材的场合，这个效果在对方回合也能发动。'),
(6195332, 'Exstellarknight Constellar Ptolemy Ω7', '超神辉星骑士 星圣 托勒密星团欧米伽7', '超神星輝士 セイクリッド・トレミスΩ７', 'XYZ Monster', 'Machine', 'LIGHT', 7, 2700, 2700, '7星怪兽×3 「超神星辉士 星圣神龙 托勒密星团Ω7」在自己主要阶段2有1次也能在自己场上的「星骑士」、「星圣」超量怪兽上面重叠来超量召唤。 ①：这张卡只要自己的墓地·除外状态的「星骑士」怪兽是7种类以上，攻击力·守备力上升2700，不受对方发动的效果影响。 ②：自己·对方回合1次，把这张卡的超量素材任意数量取除，以那个数量的对方场上的怪兽为对象才能发动。那些怪兽回到卡组。'),
(34022970, 'Ext Ryzeal', '超燃・雷热涡炉', 'エクス・ライゼオル', 'Effect Monster', 'Pyro', 'LIGHT', 4, 500, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把额外卡组1只超量怪兽送去墓地，从手卡特殊召唤。这个方法特殊召唤过的回合，自己不是4阶超量怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤的场合，若4星·4阶的怪兽以外的表侧表示怪兽不在自己场上存在则能发动。从卡组把1只雷族·炎属性怪兽加入手卡。'),
(68456353, 'Exterio''s Fang', '木龙兽之牙', 'エクストリオの牙', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有名字带有「自然」的怪兽表侧表示存在的场合才能发动。对方发动的魔法·陷阱卡的发动无效并破坏。那之后，把自己1张手卡送去墓地。'),
(95676943, 'Extinction on Schedule', '灭绝之宿命', '絶滅の定め', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段支付2000基本分才能发动。这张卡的发动后第3次的战斗阶段结束时，双方玩家必须把各自场上的卡全部送去墓地。'),
(99162522, 'EXTINGUISH!', '扑灭！', 'EXTINGUISH！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「救援ACE队」卡使用。 ①：自己场上有「救援ACE队」怪兽存在的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽破坏。自己场上有「救援ACE队 消防栓」存在的场合，再在这个回合让对方不能把这个效果破坏的怪兽以及原本卡名和那只怪兽相同的怪兽的效果发动。'),
(98828338, 'Extinguishing the Ashened', '灰灭的愤怒', '灰滅の憤怒', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只炎族·暗属性怪兽送去墓地。那之后，可以从自己墓地把1只5星以上的炎族怪兽加入手卡。这张卡的发动后，直到回合结束时自己不是炎族怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。自己的手卡·场上的怪兽作为融合素材，把1只炎族融合怪兽融合召唤。'),
(26050548, 'Extox Hydra', '额外毒海德拉', 'エクストクス・ハイドラ', 'Fusion Monster', 'Reptile', 'WATER', 4, 2000, 2000, '从额外卡组特殊召唤的自己场上的怪兽×2只以上 ①：只要这张卡在怪兽区域存在，和作为这张卡的融合素材的怪兽种类（融合·同调·超量·灵摆·连接）相同种类的对方场上的怪兽攻击力下降原本攻击力数值。 ②：这张卡给与对方1000以上的战斗伤害时才能发动。那次伤害每有1000，自己从卡组抽1张。'),
(94937430, 'Extra Buck', '临时收入', '臨時収入', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次自己的额外卡组有卡加入，给这张卡放置1个魔力指示物（最多3个）。 ②：把有3个魔力指示物放置的这张卡送去墓地才能发动。自己从卡组抽2张。'),
(7405310, 'Extra Gate', '额外之门', 'エクストラゲート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '宣言从1到12的任意等级发动。对方把额外卡组存在的1只持有宣言的等级的怪兽从游戏中除外。持有宣言的等级的怪兽不在对方的额外卡组的场合，选择自己1张手卡丢弃。'),
(95376428, 'Extra Net', '召唤限制-额外之网', '召喚制限－エクストラネット', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己或者对方从额外卡组把怪兽特殊召唤的场合把这个效果发动。从把那些怪兽特殊召唤的玩家来看的对方可以让以下效果适用。 ●从卡组抽1张。'),
(58308221, 'Extra Pendulum', '额外灵摆', 'EXP', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，自己在通常的灵摆召唤外加上只有1次，自己主要阶段可以从额外卡组把怪兽灵摆召唤。');